// Plain-file notes kept under one directory.
const fs = require('fs');
const path = require('path');

function read(root, name) {
  const base = path.resolve(root);
  const file = path.resolve(base, name);
  if (!file.startsWith(base + path.sep)) {
    return null;
  }
  if (!fs.existsSync(file) || !fs.statSync(file).isFile()) {
    return null;
  }
  return fs.readFileSync(file, 'utf8');
}

module.exports = { read };

const fs = require('fs');
const os = require('os');
const path = require('path');
const notes = require('../lib/notes');

test('reads an existing note', () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'notes-'));
  fs.writeFileSync(path.join(root, 'todo.txt'), 'milk');
  expect(notes.read(root, 'todo.txt')).toBe('milk');
});
